MATCH (s:Set {set_num: 'MULTIPACK-1'})-[:HAS_INVENTORY]->(current:Inventory)
WHERE NOT EXISTS {
  MATCH (s)-[:HAS_INVENTORY]->(newer:Inventory)
  WHERE newer.version > current.version
}
MATCH (s)-[:HAS_INVENTORY]->(version1:Inventory {version: 1})

CALL (current) {
  MATCH p = (current)-[:CONTAINS_SET|CONTAINS_MINIFIG|HAS_INVENTORY*0..]->(inv:Inventory)
  WHERE all(r IN relationships(p) WHERE
    (type(r) = 'HAS_INVENTORY' AND NOT EXISTS {
      MATCH (startNode(r))-[:HAS_INVENTORY]->(newer:Inventory)
      WHERE newer.version > endNode(r).version
    })
    OR (type(r) <> 'HAS_INVENTORY' AND r.qty > 0)
  )
  MATCH (inv)-[hp:HAS_PART]->(part:Part)
  WHERE hp.qty > 0 AND hp.is_spare = false
  RETURN collect(DISTINCT part.part_num) AS currentParts
}

CALL (version1) {
  MATCH p = (version1)-[:CONTAINS_SET|CONTAINS_MINIFIG|HAS_INVENTORY*0..]->(inv:Inventory)
  WHERE all(r IN relationships(p) WHERE
    (type(r) = 'HAS_INVENTORY' AND NOT EXISTS {
      MATCH (startNode(r))-[:HAS_INVENTORY]->(newer:Inventory)
      WHERE newer.version > endNode(r).version
    })
    OR (type(r) <> 'HAS_INVENTORY' AND r.qty > 0)
  )
  MATCH (inv)-[hp:HAS_PART]->(part:Part)
  WHERE hp.qty > 0 AND hp.is_spare = false
  RETURN collect(DISTINCT part.part_num) AS version1Parts
}

UNWIND currentParts AS part_num
WITH DISTINCT part_num, version1Parts
WHERE NOT part_num IN version1Parts
RETURN part_num
ORDER BY part_num
